The wording comes from `inst_text(inst, rng)`, so I'll fill in 'text' that way and rebuild the pass-3 prompt set.

```python
# Rebuild P3 with inst_text for non-bank instruction types
def other_inst(k, rng, task):
    i_ = rand_inst(k, rng, task); i_['text'] = inst_text(i_, rng); return i_
def make_if(kind, split, rng, combo_p=0.3):
    task = rng.choice(TT)(rng); insts = []
    if kind in BANK:
        insts.append({'type': kind, 'text': rng.choice(BANK[kind][0 if split=='choice' else 1])})
        if rng.random() < combo_p:
            k2 = rng.choice(['words','sentences','paragraphs','keyword','highlight'] + (['no_comma'] if kind!='no_comma' else ['lowercase']))
            insts.append({'type': k2, 'text': rng.choice(BANK[k2][0 if split=='choice' else 1])} if k2 in BANK else other_inst(k2, rng, task))
    else:
        insts.append(other_inst(kind, rng, task))
    return {'task': task, 'insts': insts, 'prompt': task + ' ' + ' '.join(i_['text'] for i_ in insts)}
R3 = random.Random(20261105)
_ = [R3.random() for _ in range(3)]
P3 = []
for kind, nk in [('no_comma', 120), ('lowercase', 120), ('capital', 48)] + [(o_, 19) for o_ in OTHER]:
    for _ in range(nk): P3.append(make_if(kind, 'choice', R3))
print(len(P3), Counter(tuple(sorted(i_['type'] for i_ in p_['insts'])) for p_ in P3).most_common(14))
for p_ in [P3[0], P3[3], P3[130], P3[300], P3[360]]:
    print('--', p_['prompt'][:240])
bad_ = [p_ for p_ in P3 for i_ in p_['insts'] if not isinstance(check(i_, 'hello world.'), (bool, np.bool_))]
print('checker validation issues:', len(bad_))
