Ranked by follow rate, the starting edit gives: all-caps 56%, words 58%, letter 63%, highlights 74%, keyword 74%, paragraphs 75%, no-comma 75% (n=133), capital-word count 79%, lowercase 79% (n=126), sentences 83%, repeat 84%. Math is 22/24 and multiple choice 15/16. No-comma and lowercase are now nearer the held-out 65%.

Before building anything I'll break down why the no-comma and lowercase answers fail. Is it a few convention commas or capitals (Dear X, / sign-offs / names / 'I') in an otherwise compliant answer, the whole answer ignoring the constraint, or no answer at all (cut/loop)? A gate that lowers comma or uppercase logits only fixes the first kind.

```python
# Failure anatomy for no_comma / lowercase / capital in pass 3
def count_viol(ty_, ans):
    if ty_ == 'no_comma': return ans.count(',')
    if ty_ == 'lowercase': return sum(ch.isupper() for ch in ans)
    if ty_ == 'capital': return sum(ch.islower() for ch in ans)
rows_f = []
for r_ in res3:
    if r_['kind'] != 'if': continue
    g_ = G3[[i_ for i_, gg in enumerate(G3) if gg['id'] == f'prompt/{r_["k"]+off}'][0]]
    ans = answer_of(g_['text'])
    for t_, o_ in zip(r_['types'], r_['ok']):
        if t_ in ('no_comma', 'lowercase', 'capital') and not o_:
            nv = count_viol(t_, ans) if ans else None
            letters = sum(ch.isalpha() for ch in ans) if ans else 0
            rows_f.append(dict(k=r_['k'], type=t_, combo=len(r_['types'])>1, no_ans=ans is None, cut=r_['cut'], loop=r_['loop'], n_viol=nv,
                               frac=(nv/max(1, letters if t_!='no_comma' else len(ans.split()))) if ans else None, ans_len=len(ans) if ans else 0))
dfF = pd.DataFrame(rows_f)
for t_, sub in dfF.groupby('type'):
    print(f"== {t_}: {len(sub)} failures | no answer {int(sub.no_ans.sum())} | loop {int(sub.loop.sum())} | cut {int(sub.cut.sum())} | combo {int(sub.combo.sum())}")
    ok_ = sub[~sub.no_ans]
    print('   n_viol distribution:', Counter(np.minimum(ok_.n_viol.astype(int), 20)).most_common(), '| frac median', round(float(ok_.frac.median()),3))
